<h1>Quản lý sách</h1><p><a class="button" href="<?= BASE_URL ?>/?r=admin/addBook">Thêm sách</a></p><div class="table-wrap"><table><thead><tr><th>ID</th><th>Tên</th><th>Tác giả</th><th>Giá</th><th>Tồn kho</th></tr></thead><tbody><?php foreach ($books as $book): ?><tr><td><?= (int) $book['id'] ?></td><td><?= View::escape($book['title']) ?></td><td><?= View::escape($book['author']) ?></td><td><?= number_format((float) $book['price'], 0, ',', '.') ?> ₫</td><td><?= (int) $book['stock'] ?></td></tr><?php endforeach; ?></tbody></table></div>
